INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0402', 1, 'KP0401', '多选', '下列属于对数据库安全性产生威胁的因素有（ ）。', '[{"key":"A","text":"非授权用户对数据库的恶意存取和破坏"},{"key":"B","text":"数据库中重要或敏感数据被泄露"},{"key":"C","text":"计算机系统安全环境脆弱"},{"key":"D","text":"数据库磁盘容量不足"}]', 'ABC', '教材把威胁归为三类：非授权用户恶意存取和破坏、重要或敏感数据被泄露（含 SQL 注入）、安全环境脆弱（硬件、操作系统、网络协议）。磁盘容量不足属于资源与性能问题，不是安全性威胁。', '2', '教材 P128', '可把 SQL 注入单列为一个选项。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0403', 1, 'KP0401', '简答', '简述 TCSEC/TDI 的安全级别划分，并说明 C2 级与 B1 级 DBMS 的主要特征；CC 的评估保证级如何划分？', NULL, 'TCSEC/TDI 分 D、C1、C2、B1、B2、B3、A1 四组七级，可信程度递增。C2 为受控的存取保护，在 C1 自主存取控制基础上细化，以个人身份注册并实施审计和资源隔离；B1 为标记安全保护，对数据加标记并对主体、客体实施强制存取控制和审计，是真正意义上的安全产品。CC 用 EAL1—EAL7 七个评估保证级，保证程度递增，大致对应 C1—A1。', '记忆主线是“D 最低、C 组自主存取控制、B 组强制存取控制、A1 形式化验证”。C2 的关键词是审计与资源隔离，B1 的关键词是标记与 MAC；CC 的 EAL1—EAL7 与 TCSEC 级别只是大致对应，不是一一等同。', '3', '教材 P128—130；习题 4 第 3 题', '可单独问“B1 为什么被称为真正意义的安全产品”。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0404', 1, 'KP0402', '单选', 'DBMS 提供的最外层安全保护措施是（ ）。', '[{"key":"A","text":"存取控制"},{"key":"B","text":"用户身份鉴别"},{"key":"C","text":"视图机制"},{"key":"D","text":"审计"}]', 'B', '用户进入系统前先做身份鉴别，只有合法用户才被允许进入，因此它是最外层保护；存取控制、视图、审计都在身份鉴别通过之后才发挥作用。', '1', '教材 P132', '可把“最外层”改为“事后检查”再问一次。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0405', 1, 'KP0402', '填空', '用户标识由______和______两部分组成，其中______在系统整个生命周期内唯一；智能卡鉴别常与______结合使用，以弥补智能卡数据静态、可能被截取的缺陷。', NULL, '用户名；用户标识号（UID）；UID；个人识别号（PIN）', '教材 4.2.1 明确用户标识由 username 与 UID 组成，UID 生命周期唯一；智能卡读取的数据是静态的，可能被内存扫描或网络监听截取，实际采用 PIN 与智能卡结合，二者其一被窃取仍不致身份被冒充。', '2', '教材 P132—133', '可把“UID”与“用户名”顺序打乱出选择题。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0406', 1, 'KP0403', '单选', '存取控制机制主要由哪两部分组成（ ）。', '[{"key":"A","text":"身份鉴别与入侵检测"},{"key":"B","text":"定义用户权限与合法权限检查"},{"key":"C","text":"视图定义与审计"},{"key":"D","text":"加密与解密"}]', 'B', '存取控制先把用户权限登记到数据字典形成安全规则，再在每次存取请求时查字典做合法权限检查，二者共同构成存取控制子系统；身份鉴别、入侵检测、视图、审计、加密属于其他安全措施。', '1', '教材 P133', '可问“权限登记在哪里”，答案为数据字典。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0407', 1, 'KP0403', '简答', '比较自主存取控制（DAC）与强制存取控制（MAC）的主要区别，并说明 C2、B1 级 DBMS 各支持哪一种。', NULL, 'DAC 中不同用户对不同对象有不同权限，同一对象对不同用户也有不同权限，用户还可把权限转授他人，因而灵活；MAC 中每个对象标密级、每个用户发许可证，只有合法许可证才能存取，因而严格。C2 级支持 DAC，B1 级支持 MAC，并在 B1 增加标记与强制存取控制，同时保留审计。', '区分要点是“权限由谁决定”：DAC 由数据属主自主决定并可转授，MAC 由系统按密级与许可证强制检查、用户不可感知。C2 是 DAC 加审计，B1 才引入标记与 MAC，并保留审计。', '2', '教材 P133', '可追问“为什么 DAC 仍可能无意泄露”。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0408', 1, 'KP0404', '单选', '在 GRANT 语句中，使被授权者能够把获得的权限再授予其他用户的子句是（ ）。', '[{"key":"A","text":"WITH CHECK OPTION"},{"key":"B","text":"WITH GRANT OPTION"},{"key":"C","text":"CASCADE"},{"key":"D","text":"RESTRICT"}]', 'B', 'WITH GRANT OPTION 赋予被授权者传播权；WITH CHECK OPTION 用于视图，保证增删改满足视图定义条件；CASCADE 与 RESTRICT 是 REVOKE 的收回方式，不能混用。', '1', '教材 P135', '可把四个子句放进同一道多选题。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0409', 1, 'KP0404', '综合', '已知关系模式：学生（学号，姓名，年龄，性别，家庭住址，班级号）、班级（班级号，班级名，班主任，班长）。请用 SQL 的 GRANT 语句完成：①授予用户 U1 对两个表的所有权限，并可给其他用户授权；②授予 U2 对学生表查看权限、对家庭住址更新权限；③将班级表查看权限授予所有用户；④将学生表查询、更新权限授予角色 R1；⑤将角色 R1 授予 U1，且 U1 可继续授权给其他角色。', NULL, '①GRANT ALL PRIVILEGES ON TABLE 学生,班级 TO U1 WITH GRANT OPTION; ②GRANT SELECT, UPDATE(家庭住址) ON TABLE 学生 TO U2; ③GRANT SELECT ON TABLE 班级 TO PUBLIC; ④CREATE ROLE R1; GRANT SELECT, UPDATE ON TABLE 学生 TO R1; ⑤GRANT R1 TO U1 WITH ADMIN OPTION;', '①全部权限用 ALL PRIVILEGES，可转授加 WITH GRANT OPTION；②列级 UPDATE 必须写列名；③PUBLIC 表示全体用户；④先建角色再给角色授权；⑤WITH ADMIN OPTION 使 U1 能把角色再授予其他角色。', '3', '习题 4 第 5 题；习题册 P57—58', '可把“全体用户”改为“角色”再练一次。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0410', 1, 'KP0404', '简答', '写出 GRANT 语句的一般格式，并说明哪些用户可以发出 GRANT、TO PUBLIC 的含义，以及对属性列授权时需要注意什么。', NULL, '格式：GRANT <权限>[,<权限>] ON <对象类型><对象名>[,<对象类型><对象名>] TO <用户>[,<用户>] [WITH GRANT OPTION]。发出者可以是 DBA、数据库属主，或已拥有该权限的用户；PUBLIC 表示全体用户；对属性列授权必须写明列名，给列 INSERT 权限时必须包含主码列的 INSERT 权限，否则插入会因主码为空被拒绝。', 'GRANT 的四个要素是权限、对象、用户、是否可转授。易错点是把 PUBLIC 当成某个具体用户，以及列级 INSERT 只授普通列而漏掉主码列，导致插入被主码约束拒绝。', '2', '教材 P135—136', '可让学生找出格式中哪一项可省略。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0411', 1, 'KP0405', '单选', 'REVOKE 语句中未指定 CASCADE 或 RESTRICT 时，默认行为是（ ）。', '[{"key":"A","text":"级联收回"},{"key":"B","text":"若权限已被转授则不能收回"},{"key":"C","text":"删除被授权用户"},{"key":"D","text":"同时收回该用户的所有权限"}]', 'B', 'REVOKE 默认 RESTRICT，若权限已被转授则不能收回；只有显式 CASCADE 才级联收回。REVOKE 不会删除用户，也不会波及与该权限无关的其他权限。', '2', '教材 P137', '可改成“已转授时如何收回”再问一次。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0412', 1, 'KP0405', '综合', 'U5 将对 SC 表的 INSERT 权限授予 U6（带 WITH GRANT OPTION），U6 又授予 U7（未带 WITH GRANT OPTION）。现执行 REVOKE INSERT ON TABLE SC FROM U5 CASCADE。请说明 U5、U6、U7 的权限变化；若 U6 还从其他用户处获得过 SC 表的 INSERT 权限，结果有何不同？', NULL, 'U5 的 INSERT 被收回；U6、U7 因权限直接或间接来自 U5，被级联收回。若 U6 还从其他用户处获得同一权限，则 U6 仍保留该权限，系统只收回从 U5 处获得的部分；U7 的权限来自 U6 从 U5 获得的授权链，通常随该链级联收回，但若 U7 另有其他合法授权来源，则仍保留其他来源的权限。', '级联收回沿授权链传播，只收回直接或间接来自被收回者的部分；来自其他授权者的同一权限不受影响。若用默认 RESTRICT，因 U5 已转授，收回会失败。', '3', '教材 P137—138；习题 4 第 7 题', '可把 CASCADE 换成 RESTRICT 对比结果。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0413', 1, 'KP0406', '单选', '数据库角色的本质是（ ）。', '[{"key":"A","text":"一个数据库用户"},{"key":"B","text":"一组与数据库操作相关的权限集合"},{"key":"C","text":"一张系统表"},{"key":"D","text":"一种加密算法"}]', 'B', '角色是被命名的一组权限，用于给一组具有相同权限的用户统一授权；角色不是数据库用户，也不是系统表或加密算法。角色可以授予用户或其他角色。', '1', '教材 P139', '可问“角色与用户的区别”。')
