INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0417', 1, 'KP0407', '多选', '在强制存取控制中，下列存取规则正确的有（ ）。', '[{"key":"A","text":"仅当主体许可证级别大于或等于客体密级时，主体才能读该客体"},{"key":"B","text":"仅当主体许可证级别小于或等于客体密级时，主体才能写该客体"},{"key":"C","text":"主体许可证级别越高，越可以写低密级客体"},{"key":"D","text":"主体许可证级别越低，越可以读高密级客体"}]', 'AB', '读规则要求许可证级别大于或等于密级，写规则要求许可证级别小于或等于密级。高许可证写低密级被禁止，防止高密级数据降密后泄露；低许可证也不能读高密级数据。', '2', '教材 P142', '可把“等于”边界单独拿出来问。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0418', 1, 'KP0407', '简答', '强制存取控制为什么规定“仅当主体许可证级别小于或等于客体密级时才能写客体”？请举例说明违反该规则可能造成的后果。', NULL, '该规则禁止高许可证主体写低密级客体，防止主体把高密级数据降低密级后写回，使原本绝密或机密的数据被低权限用户读到。例如绝密级用户把绝密数据恶意降为公开级再写回，所有用户都能读到，造成绝密数据泄露；因此写规则与读规则共同保证信息只能由低密级向高密级流动，不能反向流动。', '写规则的核心是防止“高密级数据降密外流”。如果只限制读而不限制写，高权限用户可以把绝密数据改成公开级再写回，随后所有用户都能读取，MAC 就形同虚设。', '3', '教材 P142', '可让学生画一条“低→高允许、高→低禁止”的信息流图。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0419', 1, 'KP0408', '综合', '已知关系模式：职工（职工号，姓名，年龄，职务，工资，部门号）、部门（部门号，名称，经理名，地址，电话号）。请用 SQL 的 GRANT 语句（加上视图机制）完成：①王明对两个表有 SELECT 权限；②李勇对两个表有 INSERT 和 DELETE 权限；③每个职工只对自己的记录有 SELECT 权限；④刘星对职工表有 SELECT 权限、对工资字段有更新权限；⑤张新具有修改两个表结构的权限；⑥周平对两个表有所有权限并可给其他用户授权；⑦杨兰能查询每个部门职工的最高、最低、平均工资，但不能查看个人工资。', NULL, '①GRANT SELECT ON TABLE 职工 TO 王明; GRANT SELECT ON TABLE 部门 TO 王明; ②GRANT INSERT,DELETE ON TABLE 职工 TO 李勇; GRANT INSERT,DELETE ON TABLE 部门 TO 李勇; ③为每个职工建立只含本人记录的视图，如 CREATE VIEW V_EMP_E01 AS SELECT * FROM 职工 WHERE 职工号=''E01''; GRANT SELECT ON V_EMP_E01 TO 该职工;（教材的 GRANT ... WHEN USER=NAME 仅作备注，MySQL 8 不支持） ④GRANT SELECT,UPDATE(工资) ON TABLE 职工 TO 刘星; ⑤GRANT ALTER ON TABLE 职工 TO 张新; GRANT ALTER ON TABLE 部门 TO 张新;（教材写 ALTER TABLE 权限，MySQL 8 用 ALTER） ⑥GRANT ALL PRIVILEGES ON TABLE 职工 TO 周平 WITH GRANT OPTION; GRANT ALL PRIVILEGES ON TABLE 部门 TO 周平 WITH GRANT OPTION; ⑦CREATE VIEW 部门工资 AS SELECT 部门.部门号,部门.名称,MAX(工资),MIN(工资),AVG(工资) FROM 职工,部门 WHERE 职工.部门号=部门.部门号 GROUP BY 部门.部门号; GRANT SELECT ON 部门工资 TO 杨兰;', '①③④⑤⑥练对象级、列级、结构修改与转授权限；教材允许 ON TABLE 表1,表2 与 ALTER TABLE 权限，MySQL 8 一条 GRANT 只能一个对象、结构修改权限名为 ALTER，故答案给出拆写；③的 WHEN USER=NAME 是部分 DBMS 扩展，MySQL 不支持，标准做法是本人记录视图；⑦用聚合视图把部门汇总与个人工资分离。', '3', '习题 4 第 6 题；习题册 P58—59', '可把⑦改为按部门分组的安全视图，再让学生写授权。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0420', 1, 'KP0408', '简答', '如何利用视图机制与授权机制实现“王平老师只能查询计算机科学与技术专业学生，张明老师可查询并增删改该专业学生”的权限控制？说明 WITH CHECK OPTION 的作用。', NULL, '先建视图 CS_Student：CREATE VIEW CS_Student AS SELECT * FROM Student WHERE Smajor=''计算机科学与技术'' WITH CHECK OPTION；再 GRANT SELECT ON CS_Student TO 王平；GRANT ALL PRIVILEGES ON CS_Student TO 张明。WITH CHECK OPTION 保证对该视图执行增删改时必须满足 Smajor=''计算机科学与技术''，防止通过视图写入不符合视图条件的数据。', '视图把“只能看本专业”的存取谓词固化到数据对象上，再在视图上授权，避免直接授予基本表权限。WITH CHECK OPTION 是视图定义的一部分，管的是写入数据是否满足视图条件，不是授权子句。', '2', '教材 P142—143；例 4.17', '可把专业条件换成班级条件再练一次。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0421', 1, 'KP0409', '单选', '数据库审计属于（ ）安全机制。', '[{"key":"A","text":"事前预防"},{"key":"B","text":"事中控制"},{"key":"C","text":"事后检查"},{"key":"D","text":"数据加密"}]', 'C', '审计把用户操作记录到审计日志，供事后监控、重现事件、追查非法存取；事前靠身份鉴别与入侵检测，事中靠存取控制，审计是事后检查。', '1', '教材 P143', '可把“事前/事中/事后”三组措施做成匹配题。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0422', 1, 'KP0409', '简答', '简述审计事件的主要类别、审计功能的主要内容，以及 AUDIT/NOAUDIT 与 BY ACCESS/BY SESSION 的含义。', NULL, '审计事件分服务器事件、系统权限、语句事件、模式对象事件四类。审计功能包括多种审计查阅方式、多套审计规则、审计分析与报表、审计日志管理：先转储后删除，只允许审计员查阅和转储，禁止普通用户新增修改。AUDIT 设置审计，NOAUDIT 取消审计；BY ACCESS 对每次审计操作都记录，BY SESSION 对每次会话中同类操作只记录最早一次。用户级审计任何用户可设，系统级审计只能由 DBA 设置。', '审计的四类事件按“服务器—权限—语句—对象”从粗到细排列；功能重点是日志管理与审计员专属权限。BY ACCESS 与 BY SESSION 的区别是“每次”与“每会话最早一次”，常被记反。', '3', '教材 P143—145', '可只问 BY ACCESS 与 BY SESSION 的区别。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0423', 1, 'KP0410', '单选', '关于链路加密与端到端加密，下列说法正确的是（ ）。', '[{"key":"A","text":"链路加密只加密报文，不加密报头"},{"key":"B","text":"端到端加密只加密报文，不加密报头"},{"key":"C","text":"端到端加密对报文和报头都加密"},{"key":"D","text":"链路加密不需要中间节点参与"}]', 'B', '链路加密对报文和报头都加密，需要中间节点密码设备；端到端加密在发送端加密、接收端解密，只加密报文不加密报头，中间节点不需要密码设备，但报头可能被监听。', '2', '教材 P145—146', '可把 SSL 归入端到端加密再问一次。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0424', 1, 'KP0410', '填空', '存储加密分为______和______两种方式；传输加密常用______和______；SSL 属于______加密方式；SSL 会话密钥的生命周期仅限于______。', NULL, '透明存储加密；非透明存储加密；链路加密；端到端加密；端到端；本次通信', '透明存储加密是内核级、对用户隐蔽；非透明通过多个加密函数实现。传输加密分链路与端到端：链路加密对报头和报文都加密，端到端只加密报文不加密报头。SSL 是端到端方案，会话密钥仅限本次通信，避免固定密钥的存储问题。', '2', '教材 P145—146', '可把链路加密与端到端加密的报头差异做成选择题。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0425', 1, 'KP0411', '简答', '分别说明推理控制、隐蔽信道、数据隐私与“三权分立”要解决的问题，并给出一个推理控制或隐蔽信道的例子。', NULL, '推理控制防止用户利用函数依赖、敏感关联等从可访问的低密级信息推导出无权访问的高密级信息；隐蔽信道防止高安全等级用户利用系统机制向低安全等级用户传递信息；数据隐私控制个人数据在收集、存储、处理、发布各阶段不被非法获取，发布时用准标识符与 k 匿名、l 多样性、t 临近等标准；三权分立把数据库管理员过于集中的权限拆分，避免超级用户不受检查。例子：职务→工资函数依赖，同级职务用户可由自己工资推出他人工资；或利用 UNIQUE 列插入成功/失败约定信息位。', '四项都针对 MAC 之外或 DAC/MAC 未覆盖的泄露路径：推理控制防“推导”，隐蔽信道防“旁路传递”，数据隐私防“发布与关联识别”，三权分立防“管理员权限过大”。答题要抓住各自的防范对象，不能只说名词。', '3', '教材 P147—148', '可只让学生设计一个隐蔽信道场景。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0426', 1, 'KP0411', '单选', '数据库推理控制主要防范的是（ ）。', '[{"key":"A","text":"用户利用函数依赖等从可访问数据推出更高密级数据"},{"key":"B","text":"高密级用户利用 UNIQUE 约束向低密级用户传递信息"},{"key":"C","text":"审计日志被普通用户修改"},{"key":"D","text":"传输报文被窃听或篡改"}]', 'A', '推理控制防的是“推导”：用户利用函数依赖、敏感关联和背景知识，从自己有权访问的低密级数据推出无权访问的高密级数据。B 属于隐蔽信道，C 属于审计日志管理，D 属于传输加密要解决的问题。', '2', '教材 P147', '可把推理控制与隐蔽信道的例子互换出题。')
